/**
 * Debounce function implementation.
 *
 * @param {function} func The function to be debounced.
 * @param {number} delay The time in milliseconds to wait after the last call.
 * @returns {function} The debounced version of the function.
 */
function debounce(func, delay) {
  let timeoutId; // Variable to hold the timer ID

  // Return the new function that will be called instead
  return function(...args) {
    // 'this' context is preserved for the original function call
    const context = this;

    // 1. Clear the previous timer: If the function is called again before the delay passes,
    //    it cancels the previously scheduled execution.
    clearTimeout(timeoutId);

    // 2. Set a new timer: Schedule the function to run after the specified delay.
    timeoutId = setTimeout(() => {
      // Execute the original function with the correct context and arguments
      func.apply(context, args);
    }, delay);
  };
}

// --- Example Usage ---

// 1. The function we want to debounce (e.g., an expensive API call)
function handleSearchInput(searchTerm) {
  console.log(`[API Call] Searching for: "${searchTerm}"`);
}

// 2. Create the debounced version, waiting 500ms
const debouncedSearch = debounce(handleSearchInput, 500);

// 3. Simulate rapid user input (typing quickly)
console.log("Simulating rapid typing...");

debouncedSearch("a");
debouncedSearch("ap");
debouncedSearch("app");
debouncedSearch("appl");
debouncedSearch("apple"); // This is the last call

// After 500ms of silence, only ONE call will execute:
setTimeout(() => {
    console.log("\n--- 500ms passed. Only the final search should have executed. ---");
}, 1000);
```

